example:
/* 1) 正午白光 */
ssp.lightTool.createDirectionalLight({ color: '#ffffff', intensity: 0.8, position: { x: 0, y: 500, z: 0 } });

/* 2) 黄昏暖光 */
ssp.lightTool.createDirectionalLight({ color: '#fff5d8', intensity: 1, position: { x: 100, y: 200, z: 50 } });

/* 3) 侧光 (打出侧面阴影) */
ssp.lightTool.createDirectionalLight({ color: '#ffffff', intensity: 1.2, position: { x: 500, y: 100, z: 0 }, target: { x: 0, y: 0, z: 0 } });
